def span(xs):
    b = {}
    for x in xs:
        while x:
            p = x.bit_length()-1
            if p in b: x ^= b[p]
            else:
                b[p] = x
                break
    return b

def rem(b,x):
    for p,y in sorted(b.items(),reverse=True):
        if (x>>p)&1: x ^= y
    return x

def kernel_on(inputs, transform):
    piv, out = {}, []
    for a in inputs:
        x,w = transform(a),a
        while x:
            p=x.bit_length()-1
            if p not in piv:
                piv[p]=(x,w)
                break
            y,z=piv[p];x^=y;w^=z
        if not x: out.append(w)
    return list(span(out).values())

def filt(v,n):
